	b.WriteString("## 推移\n\n")
	b.WriteString("| 回 | 日付 | スキル | model | scope | 全件 | 採択 | 保留 | 却下 |\n")
	b.WriteString("| --- | --- | --- | --- | --- | --- | --- | --- | --- |\n")
	for i, run := range doc.Runs {
		adopted, held, rejected := 0, 0, 0
		for _, fd := range run.Findings {
			switch fd.Verdict {
			case "adopted":
				adopted++
			case "held":
				held++
			case "rejected":
				rejected++
			}
		}
